/*
 * cuda_hashx.cu — CUDA backend for Anubis HashX challenges.
 *
 * The HashX program generated by src/hashx.c is uploaded once; each CUDA
 * thread expands its own 512-bit register file from the SipHash key + nonce,
 * interprets the program, finalizes and checks the leading zero bits.
 * Enabled with ANUBIS_GPU_HASHX=1; hits are re-verified by the CPU.
 */

#include <cuda_runtime.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HX_MAX_INSTR 512
#define HX_CHUNK (1u << 22)

typedef struct {
    uint32_t count;
    uint32_t pad[3];
    uint32_t nonces[8];
    uint32_t hashes[8][8];
} hx_results;

typedef struct {
    uint64_t k0, k1, k2, k3;
} hx_keys;

__device__ __forceinline__ uint64_t rotl64(uint64_t x, int n) {
    return (x << n) | (x >> (64 - n));
}

__device__ __forceinline__ uint64_t rotr64(uint64_t x, int n) {
    return (x >> n) | (x << (64 - n));
}

#define SIPROUND(v0, v1, v2, v3)                                              \
    do {                                                                      \
        v0 += v1; v2 += v3; v1 = rotl64(v1, 13);                              \
        v3 = rotl64(v3, 16); v1 ^= v0; v3 ^= v2;                              \
        v0 = rotl64(v0, 32); v2 += v1; v0 += v3;                              \
        v1 = rotl64(v1, 17); v3 = rotl64(v3, 21);                             \
        v1 ^= v2; v3 ^= v0; v2 = rotl64(v2, 32);                              \
    } while (0)

__device__ __forceinline__ int64_t smulhi64(int64_t a, int64_t b) {
    int64_t hi = (int64_t)__umul64hi((uint64_t)a, (uint64_t)b);
    if (a < 0) {
        hi -= b;
    }
    if (b < 0) {
        hi -= a;
    }
    return hi;
}

__global__ void hashx_kernel(hx_keys keys, const uint4 *prog,
                             uint32_t code_size, uint32_t difficulty,
                             uint32_t base, uint32_t count, hx_results *res) {
    uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t r[8];
    uint64_t v0, v1, v2, v3;
    int target = 0;
    int be = 1;
    uint32_t result = 0;
    int i;
    uint64_t w[4];
    uint8_t dg[32];
    int ok = 1;
    uint32_t nonce;

    if (idx >= count) {
        return;
    }
    nonce = base + idx;
    v0 = keys.k0;
    v1 = keys.k1;
    v2 = keys.k2;
    v3 = keys.k3;
    v1 ^= 0xeeULL;
    v3 ^= (uint64_t)nonce;
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    v0 ^= (uint64_t)nonce;
    v2 ^= 0xeeULL;
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    r[0] = v0;
    r[1] = v1;
    r[2] = v2;
    r[3] = v3;
    v1 ^= 0xddULL;
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    SIPROUND(v0, v1, v2, v3);
    r[4] = v0;
    r[5] = v1;
    r[6] = v2;
    r[7] = v3;

    i = 0;
    while (i < (int)code_size) {
        uint4 in = prog[i];
        uint32_t op = in.x;
        uint32_t dst = in.y;
        uint32_t src = in.z;
        uint32_t imm = in.w;
        switch (op) {
        case 0: /* UMULH_R */
            result = (uint32_t)__umul64hi(r[dst], r[src]);
            r[dst] = __umul64hi(r[dst], r[src]);
            break;
        case 1: /* SMULH_R */
            r[dst] = (uint64_t)smulhi64((int64_t)r[dst], (int64_t)r[src]);
            result = (uint32_t)r[dst];
            break;
        case 2: r[dst] *= r[src]; break;
        case 3: r[dst] -= r[src]; break;
        case 4: r[dst] ^= r[src]; break;
        case 5: r[dst] += r[src] << (imm & 63u); break;
        case 6: r[dst] = rotr64(r[dst], (int)(imm & 63u)); break;
        case 7: r[dst] += (uint64_t)(int64_t)(int32_t)imm; break;
        case 8: r[dst] ^= (uint64_t)(int64_t)(int32_t)imm; break;
        case 9: target = i; break;
        case 10: /* BRANCH */
            if (be && (result & imm) == 0) {
                i = target;
                be = 0;
            }
            break;
        default: break;
        }
        i++;
    }

    r[0] += keys.k0;
    r[1] += keys.k1;
    r[6] += keys.k2;
    r[7] += keys.k3;
    v0 = r[0]; v1 = r[1]; v2 = r[2]; v3 = r[3];
    SIPROUND(v0, v1, v2, v3);
    r[0] = v0; r[1] = v1; r[2] = v2; r[3] = v3;
    v0 = r[4]; v1 = r[5]; v2 = r[6]; v3 = r[7];
    SIPROUND(v0, v1, v2, v3);
    r[4] = v0; r[5] = v1; r[6] = v2; r[7] = v3;
    w[0] = r[0] ^ r[4];
    w[1] = r[1] ^ r[5];
    w[2] = r[2] ^ r[6];
    w[3] = r[3] ^ r[7];
    for (i = 0; i < 4; i++) {
        for (int j = 0; j < 8; j++) {
            dg[8 * i + j] = (uint8_t)(w[i] >> (8 * j));
        }
    }
    for (uint32_t b = 0; b < difficulty; b++) {
        if (((dg[b >> 3] >> (7u - (b & 7u))) & 1u) != 0u) {
            ok = 0;
            break;
        }
    }
    if (ok) {
        uint32_t slot = atomicAdd(&res->count, 1u);
        if (slot < 8u) {
            res->nonces[slot] = nonce;
            for (i = 0; i < 8; i++) {
                res->hashes[slot][i] = ((uint32_t)dg[4 * i] << 24) |
                                       ((uint32_t)dg[4 * i + 1] << 16) |
                                       ((uint32_t)dg[4 * i + 2] << 8) |
                                       (uint32_t)dg[4 * i + 3];
            }
        }
    }
}

/* ------------------------------ host side ------------------------------ */

static struct {
    int inited;
    int available;
    int ndev;
    pthread_mutex_t mu;
    uint4 *d_prog[8];
    hx_results *d_res[8];
    hx_results h_res;
    char info[160];
} g_hx = { 0, 0, 0, PTHREAD_MUTEX_INITIALIZER, {0}, {0}, {0}, {0} };

static double hx_now(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

static uint32_t hx_env_u32(const char *name, uint32_t def) {
    const char *s = getenv(name);
    if (s != NULL && *s != '\0') {
        return (uint32_t)strtoul(s, NULL, 0);
    }
    return def;
}

static int hx_init(void) {
    int count = 0;
    if (g_hx.inited) {
        return g_hx.available;
    }
    g_hx.inited = 1;
    {
        const char *off = getenv("ANUBIS_NO_CUDA");
        if (off != NULL && off[0] != '\0' && off[0] != '0') {
            return 0;
        }
    }
    if (cudaGetDeviceCount(&count) != cudaSuccess || count <= 0) {
        return 0;
    }
    if (count > 8) {
        count = 8;
    }
    for (int i = 0; i < count; i++) {
        cudaDeviceProp prop;
        if (cudaSetDevice(i) != cudaSuccess ||
            cudaGetDeviceProperties(&prop, i) != cudaSuccess) {
            return 0;
        }
        if (cudaMalloc((void **)&g_hx.d_prog[i],
                       (size_t)HX_MAX_INSTR * sizeof(uint4)) != cudaSuccess ||
            cudaMalloc((void **)&g_hx.d_res[i], sizeof(hx_results)) !=
                cudaSuccess) {
            return 0;
        }
        if (count == 1) {
            snprintf(g_hx.info, sizeof(g_hx.info), "CUDA HashX: %.96s", prop.name);
        } else {
            snprintf(g_hx.info, sizeof(g_hx.info), "CUDA HashX: %.90s x%d",
                     prop.name, count);
        }
    }
    if (cudaSetDevice(0) != cudaSuccess) {
        return 0;
    }
    g_hx.ndev = count;
    g_hx.available = 1;
    return 1;
}

int anubis_cuda_hashx_available(void) {
    return hx_init();
}

const char *anubis_cuda_hashx_info(void) {
    if (!hx_init()) {
        return NULL;
    }
    return g_hx.info;
}

static void hx_hex(const uint32_t w[8], char out[65]) {
    static const char hexd[] = "0123456789abcdef";
    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 4; j++) {
            unsigned v = (w[i] >> (8 * (3 - j))) & 0xFFu;
            out[(4 * i + j) * 2 + 0] = hexd[v >> 4];
            out[(4 * i + j) * 2 + 1] = hexd[v & 0xFu];
        }
    }
    out[64] = '\0';
}

/*
 * Returns 0 on a hit (caller re-verifies with the CPU), 1 if the range was
 * exhausted, -1 on backend failure.
 */
int anubis_cuda_hashx_solve(const void *state, size_t state_size, int difficulty,
                            uint64_t max_nonce, double budget_ms,
                            uint32_t *out_nonce, char out_hex[65],
                            double *out_ms) {
    uint64_t keys[4];
    uint32_t prog[HX_MAX_INSTR * 4];
    size_t ninstr = 0;
    hx_keys k;
    uint32_t chunk;
    uint64_t base = 0;
    uint64_t maxn;
    double t0;
    int rc = 1;

    if (state == NULL || out_nonce == NULL || out_hex == NULL) {
        return -1;
    }
    if (hashx_export(state, state_size, keys, prog, &ninstr) != 0) {
        return -1;
    }
    if (!hx_init()) {
        return -1;
    }
    pthread_mutex_lock(&g_hx.mu);
    t0 = hx_now();
    k.k0 = keys[0];
    k.k1 = keys[1];
    k.k2 = keys[2];
    k.k3 = keys[3];
    for (int d = 0; d < g_hx.ndev; d++) {
        cudaSetDevice(d);
        if (cudaMemcpy(g_hx.d_prog[d], prog, ninstr * sizeof(uint4),
                       cudaMemcpyHostToDevice) != cudaSuccess) {
            pthread_mutex_unlock(&g_hx.mu);
            return -1;
        }
    }
    chunk = hx_env_u32("ANUBIS_CUDA_HASHX_CHUNK", HX_CHUNK);
    if (chunk < 1024u) {
        chunk = 1024u;
    }
    if (chunk > (1u << 26)) {
        chunk = 1u << 26;
    }
    maxn = max_nonce > 0xFFFFFFFFull ? 0xFFFFFFFFull : max_nonce;

    while (base <= maxn) {
        int launched = 0;
        int found = 0;
        uint32_t best = 0;
        uint32_t bh[8];
        for (int d = 0; d < g_hx.ndev; d++) {
            uint64_t b = base + (uint64_t)d * chunk;
            uint32_t cnt;
            unsigned blocks;
            if (b > maxn) {
                break;
            }
            cnt = (uint32_t)((maxn - b + 1) < (uint64_t)chunk
                                 ? (maxn - b + 1)
                                 : (uint64_t)chunk);
            cudaSetDevice(d);
            if (cudaMemset(g_hx.d_res[d], 0, sizeof(hx_results)) != cudaSuccess) {
                rc = -1;
                goto done;
            }
            blocks = (cnt + 255u) / 256u;
            hashx_kernel<<<blocks, 256>>>(k, g_hx.d_prog[d], (uint32_t)ninstr,
                                          (uint32_t)difficulty, (uint32_t)b,
                                          cnt, g_hx.d_res[d]);
            if (cudaGetLastError() != cudaSuccess) {
                rc = -1;
                goto done;
            }
            launched++;
        }
        if (launched == 0) {
            break;
        }
        for (int d = 0; d < launched; d++) {
            cudaSetDevice(d);
            if (cudaDeviceSynchronize() != cudaSuccess ||
                cudaMemcpy(&g_hx.h_res, g_hx.d_res[d], sizeof(hx_results),
                           cudaMemcpyDeviceToHost) != cudaSuccess) {
                rc = -1;
                goto done;
            }
            if (g_hx.h_res.count > 0) {
                uint32_t n = g_hx.h_res.nonces[0];
                if (!found || n < best) {
                    found = 1;
                    best = n;
                    memcpy(bh, g_hx.h_res.hashes[0], sizeof(bh));
                }
            }
        }
        if (found) {
            hx_hex(bh, out_hex);
            *out_nonce = best;
            if (out_ms != NULL) {
                *out_ms = (hx_now() - t0) * 1000.0;
            }
            rc = 0;
            goto done;
        }
        base += (uint64_t)launched * chunk;
        if (budget_ms > 0.0 && (hx_now() - t0) * 1000.0 > budget_ms) {
            rc = 1;
            goto done;
        }
    }

done:
    for (int d = 0; d < g_hx.ndev; d++) {
        cudaSetDevice(d);
        (void)cudaGetLastError();
    }
    pthread_mutex_unlock(&g_hx.mu);
    return rc;
}

/* Single-nonce digest for testing/debugging. */
int anubis_cuda_hashx_digest(const void *state, size_t state_size,
                             uint32_t nonce, uint8_t out[32]) {
    uint64_t keys[4];
    uint32_t prog[HX_MAX_INSTR * 4];
    size_t ninstr = 0;
    hx_keys k;
    unsigned blocks = 1;

    if (state == NULL || out == NULL ||
        hashx_export(state, state_size, keys, prog, &ninstr) != 0 ||
        !hx_init()) {
        return -1;
    }
    k.k0 = keys[0];
    k.k1 = keys[1];
    k.k2 = keys[2];
    k.k3 = keys[3];
    pthread_mutex_lock(&g_hx.mu);
    cudaSetDevice(0);
    if (cudaMemcpy(g_hx.d_prog[0], prog, ninstr * sizeof(uint4),
                   cudaMemcpyHostToDevice) != cudaSuccess ||
        cudaMemset(g_hx.d_res[0], 0, sizeof(hx_results)) != cudaSuccess) {
        pthread_mutex_unlock(&g_hx.mu);
        return -1;
    }
    hashx_kernel<<<blocks, 1>>>(k, g_hx.d_prog[0], (uint32_t)ninstr, 0u, nonce,
                                1u, g_hx.d_res[0]);
    if (cudaGetLastError() != cudaSuccess ||
        cudaDeviceSynchronize() != cudaSuccess ||
        cudaMemcpy(&g_hx.h_res, g_hx.d_res[0], sizeof(hx_results),
                   cudaMemcpyDeviceToHost) != cudaSuccess ||
        g_hx.h_res.count == 0) {
        pthread_mutex_unlock(&g_hx.mu);
        return -1;
    }
    for (int i = 0; i < 8; i++) {
        uint32_t w = g_hx.h_res.hashes[0][i];
        out[4 * i + 0] = (uint8_t)(w >> 24);
        out[4 * i + 1] = (uint8_t)(w >> 16);
        out[4 * i + 2] = (uint8_t)(w >> 8);
        out[4 * i + 3] = (uint8_t)w;
    }
    pthread_mutex_unlock(&g_hx.mu);
    return 0;
}
